{"Table":"bk_tb_feedback_auto_review_promotion_candidate","Create Table":"CREATE TABLE `bk_tb_feedback_auto_review_promotion_candidate` (\n  `id` varchar(36) NOT NULL,\n  `owner` varchar(64) NOT NULL,\n  `type` enum('alias','rule','threshold','model','operational_policy') NOT NULL,\n  `status` enum('candidate','shadow_validated','approved','rejected','active','rolled_back') NOT NULL,\n  `origin` enum('human_divergence','shadow_comparison','metric_regression','alias_suggestion','training_run','manual_adjustment') NOT NULL,\n  `candidateVersion` varchar(64) NOT NULL,\n  `baseReviewVersion` varchar(64) NOT NULL,\n  `evidence` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`evidence`)),\n  `expectedImpact` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`expectedImpact`)),\n  `knownRisk` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`knownRisk`)),\n  `rollbackPlan` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`rollbackPlan`)),\n  `createdBy` varchar(64) NOT NULL,\n  `approvedBy` varchar(64) DEFAULT NULL,\n  `approvedAt` datetime DEFAULT NULL,\n  `appliedAt` datetime DEFAULT NULL,\n  `rolledBackAt` datetime DEFAULT NULL,\n  `notes` text DEFAULT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `rejectedBy` varchar(64) DEFAULT NULL,\n  `appliedBy` varchar(64) DEFAULT NULL,\n  `rolledBackBy` varchar(64) DEFAULT NULL,\n  `rejectedAt` datetime DEFAULT NULL,\n  `rollbackReason` text DEFAULT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `IDX_feedback_auto_review_candidate_version` (`owner`,`candidateVersion`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci"}